#!/usr/bin/env bash
set -euo pipefail

echo "Restoring AI Data Marketplace into the current Codespace..."

ARCHIVE_B64="$(mktemp)"
ARCHIVE_ZIP="$(mktemp --suffix=.zip)"
EXTRACT_DIR="$(mktemp -d)"

cleanup() {
  rm -f "$ARCHIVE_B64" "$ARCHIVE_ZIP"
  rm -rf "$EXTRACT_DIR"
}
trap cleanup EXIT

cat > "$ARCHIVE_B64" <<'ARCHIVE_DATA'

ARCHIVE_DATA

base64 -d "$ARCHIVE_B64" > "$ARCHIVE_ZIP"
unzip -q "$ARCHIVE_ZIP" -d "$EXTRACT_DIR"

PROJECT_DIR="$EXTRACT_DIR/ai-data-marketplace-main"

if [ ! -f "$PROJECT_DIR/package.json" ] || [ ! -d "$PROJECT_DIR/apps" ]; then
  echo "ERROR: The deployment package did not contain the expected project files."
  exit 1
fi

# Copy the project into the current repository, but never touch .git.
cp -R "$PROJECT_DIR"/. .

echo
echo "RESTORE COMPLETE"
echo "Top-level files:"
find . -maxdepth 2 -type f -not -path './.git/*' | sort | head -80
echo
echo "Git status:"
git status --short
echo
echo "Next step:"
echo 'git add . && git commit -m "Restore AI Data Marketplace application" && git push origin main'
